const input = $json;
const webhookBody = input.body && typeof input.body === 'object' ? input.body : {};
const raw = input.rawPayload && typeof input.rawPayload === 'object' ? input.rawPayload : (Object.keys(webhookBody).length ? webhookBody : input);
const rawBody = raw.body && typeof raw.body === 'object' ? raw.body : {};
const rawData = raw.data && typeof raw.data === 'object' ? raw.data : {};
const bodyData = rawBody.data && typeof rawBody.data === 'object' ? rawBody.data : {};

const labels = {
  name: ['name', 'full name', 'full_name', 'contact name', 'your name'],
  email: ['email', 'email address', 'contact email', 'your email'],
  business: ['business', 'business name', 'company', 'company name', 'organization'],
  automationRequest: ['automation request', 'automation', 'request', 'what do you need automated', 'lead request', 'need', 'primary need', 'use case'],
  package: ['package', 'select package', 'selected package', 'plan', 'offer'],
  source: ['source', 'utm_source', 'utm source', 'referral source', 'how did you hear about us', 'where did you hear about us', 'form', 'form name'],
  priority: ['priority', 'lead priority', 'urgency'],
  budget: ['budget', 'monthly budget', 'project budget', 'estimated budget']
};

const stringify = (value) => {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value.trim();
  if (typeof value === 'number' || typeof value === 'boolean') return String(value).trim();
  if (Array.isArray(value)) return value.map(stringify).filter(Boolean).join(', ');
  if (typeof value === 'object') {
    for (const key of ['text', 'label', 'name', 'title', 'email', 'value', 'answer']) {
      if (value[key] !== undefined && value[key] !== value) {
        const text = stringify(value[key]);
        if (text) return text;
      }
    }
    return '';
  }
  return String(value).trim();
};

const normalizeKey = (value) => stringify(value).toLowerCase().replace(/[^a-z0-9]+/g, '');
const canonicalByAlias = new Map();
for (const [canonical, aliases] of Object.entries(labels)) {
  for (const alias of [canonical, ...aliases]) canonicalByAlias.set(normalizeKey(alias), canonical);
}

const fieldValues = {};
const displayCandidates = [];

const optionMapFor = (field) => {
  const options = new Map();
  for (const option of Array.isArray(field?.options) ? field.options : []) {
    const id = stringify(option.id ?? option.value ?? option.key);
    const label = stringify(option.text ?? option.label ?? option.name ?? option.title ?? option.value ?? option.id);
    if (id) options.set(id, label || id);
  }
  return options;
};

const answerFromField = (field) => {
  const answer = field?.answer ?? field?.value ?? field?.text ?? field?.email ?? field?.selected ?? field?.choices ?? field?.selectedOptions;
  const options = optionMapFor(field);
  if (Array.isArray(answer)) {
    return answer.map((item) => options.get(stringify(item)) || stringify(item)).filter(Boolean).join(', ');
  }
  return options.get(stringify(answer)) || stringify(answer);
};

const labelsFromField = (field) => {
  const nestedField = field?.field && typeof field.field === 'object' ? field.field : {};
  return [
    field?.label,
    field?.title,
    field?.name,
    field?.key,
    field?.id,
    field?.question,
    nestedField.label,
    nestedField.title,
    nestedField.name,
    nestedField.key,
    nestedField.id
  ].map(stringify).filter(Boolean);
};

const addValue = (label, value) => {
  const canonical = canonicalByAlias.get(normalizeKey(label));
  const answer = stringify(value);
  if (canonical && answer && (!fieldValues[canonical] || fieldValues[canonical].includes('→'))) fieldValues[canonical] = answer;
};

const ingestField = (field) => {
  if (!field || typeof field !== 'object') return;
  const answer = answerFromField(field);
  for (const label of labelsFromField(field)) addValue(label, answer);
  if (answer.includes('→')) displayCandidates.push(answer);
};

const candidateArrays = [
  bodyData.fields,
  rawBody.fields,
  rawData.fields,
  raw.fields,
  bodyData.answers,
  rawBody.answers,
  rawData.answers,
  raw.answers,
  input.answers
];
for (const fields of candidateArrays) {
  if (Array.isArray(fields)) fields.forEach(ingestField);
}

for (const container of [bodyData, rawBody, rawData, raw, input]) {
  if (!container || typeof container !== 'object' || Array.isArray(container)) continue;
  for (const [key, value] of Object.entries(container)) {
    if (['body', 'data', 'fields', 'answers', 'rawPayload', 'headers', 'query', 'params'].includes(key)) continue;
    if (value && typeof value === 'object') continue;
    addValue(key, value);
    if (stringify(value).includes('→')) displayCandidates.push(stringify(value));
  }
}

const displayAliases = Object.values(labels).flat();
const parseDisplayCandidate = (candidate) => {
  const hits = [];
  for (const alias of displayAliases) {
    const pattern = new RegExp(`(^|\\s)${alias.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*(?:→|:|-)`, 'gi');
    let match;
    while ((match = pattern.exec(candidate)) !== null) {
      hits.push({ alias, start: match.index + match[1].length, valueStart: pattern.lastIndex });
    }
  }
  hits.sort((a, b) => a.start - b.start);
  for (let index = 0; index < hits.length; index += 1) {
    const current = hits[index];
    const next = hits[index + 1];
    addValue(current.alias, candidate.slice(current.valueStart, next ? next.start : candidate.length));
  }
};
for (const candidate of displayCandidates) parseDisplayCandidate(candidate);

const pick = (canonical, fallback = 'Not provided') => stringify(fieldValues[canonical]) || fallback;
const email = pick('email', '').toLowerCase();
const receivedAt = stringify(input.receivedAt ?? raw.receivedAt ?? rawData.createdAt ?? rawData.submittedAt) || new Date().toISOString();
const leadId = stringify(input.leadId ?? raw.leadId) || `lead_${Date.now()}`;
const eventType = stringify(raw.eventType ?? raw.type ?? input.eventType ?? 'FORM_RESPONSE');

if (eventType && eventType !== 'FORM_RESPONSE') {
  return [{ json: { accepted: false, reason: 'Ignored non-FORM_RESPONSE Tally event', eventType, receivedAt, rawPreview: JSON.stringify(raw).slice(0, 1200) } }];
}

const packageValue = pick('package');
const packageKey = packageValue === 'Not provided' ? '' : normalizeKey(packageValue);
const nextStep = packageKey.includes('starter') || packageKey === '49'
  ? { type: 'stripe_payment_link', label: 'Starter System', amount: 49, url: process.env.STRIPE_PAYMENT_LINK_STARTER || 'https://buy.stripe.com/...' }
  : packageKey.includes('pro') || packageKey.includes('followup') || packageKey === '149'
    ? { type: 'stripe_payment_link', label: 'Pro Follow-Up System', amount: 149, url: process.env.STRIPE_PAYMENT_LINK_PRO || 'https://buy.stripe.com/...' }
    : packageKey.includes('custom') || packageKey.includes('build') || packageKey.includes('booking')
      ? { type: 'booking_link', label: 'Custom Build', url: process.env.CUSTOM_BUILD_BOOKING_LINK || 'https://cal.com/your-booking-link' }
      : { type: 'manual_follow_up', label: 'Manual Follow-Up', url: process.env.CUSTOM_BUILD_BOOKING_LINK || 'https://cal.com/your-booking-link' };

return [{
  json: {
    accepted: true,
    leadId,
    name: pick('name', 'Unknown Lead'),
    email,
    business: pick('business'),
    automationRequest: pick('automationRequest', 'Lead alert'),
    package: packageValue,
    source: pick('source', stringify(rawData.formName ?? bodyData.formName) || 'Tally'),
    receivedAt,
    priority: pick('priority', 'Normal'),
    emailExists: Boolean(email),
    need: pick('automationRequest', 'Lead alert'),
    budget: stringify(fieldValues.budget) || 'Not provided',
    leadStatus: stringify(input.leadStatus ?? input.status) || 'New Lead',
    status: stringify(input.leadStatus ?? input.status) || 'New Lead',
    paymentStatus: stringify(input.paymentStatus) || 'Pending',
    paymentNextStepType: nextStep.type,
    paymentNextStepLabel: nextStep.label,
    paymentNextStepUrl: nextStep.url || '',
    paymentAmount: nextStep.amount || '',
    formId: stringify(bodyData.formId ?? rawData.formId ?? raw.formId ?? input.formId),
    responseId: stringify(bodyData.responseId ?? rawData.responseId ?? raw.responseId ?? input.responseId),
    rawPreview: JSON.stringify(raw).slice(0, 1200)
  }
}];

